  body += docxParagraph(`إجمالي الطلاب الأقل من ${result.threshold}%: ${result.at_risk_count} طالبًا.`, {size: 19, color: "7A4A00", bold: true, shading: "FFF8EA", borderRight: "F7941D", before: 80, after: 120, keepLines: true});

